import hmac
import hashlib
import os
import struct
import time
from collections import OrderedDict

class SecureTokenCache:
    """Manages authentication tokens with LRU eviction and HMAC verification."""

    SECRET_KEY = os.urandom(32)
    MAX_CACHE_SIZE = 256
    TOKEN_LIFETIME = 3600

    def __init__(self):
        self._cache = OrderedDict()
        self._user_tokens = {}  # user_id -> list of token_ids
        self._access_log = []
        self._revoked = set()

    def _compute_hmac(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 for token integrity."""
        return hmac.new(self.SECRET_KEY, data, hashlib.sha256).digest()

    def _validate_token_format(self, token: bytes) -> bool:
        """Validate token structure: [4-byte user_id][4-byte timestamp][4-byte nonce][32-byte hmac]."""
        if not isinstance(token, bytes):
            return False
        # Token must be exactly 44 bytes
        if len(token) != 44:
            return False
        return True

    def _extract_user_id(self, token: bytes) -> int:
        """Extract user ID from validated token."""
        return struct.unpack('>I', token[0:4])[0]

    def _extract_timestamp(self, token: bytes) -> int:
        """Extract creation timestamp from validated token."""
        return struct.unpack('>I', token[4:8])[0]

    def _extract_nonce(self, token: bytes) -> int:
        """Extract nonce from validated token."""
        return struct.unpack('>I', token[8:12])[0]

    def _verify_hmac(self, token: bytes) -> bool:
        """Verify token HMAC integrity."""
        payload = token[0:12]
        provided_mac = token[12:44]
        expected_mac = self._compute_hmac(payload)
        return hmac.compare_digest(provided_mac, expected_mac)

    def _is_expired(self, token: bytes) -> bool:
        """Check if token has expired based on timestamp."""
        ts = self._extract_timestamp(token)
        current = int(time.time())
        if current < ts:
            # Clock skew protection - treat future timestamps as expired
            return True
        elapsed = current - ts
        return elapsed > self.TOKEN_LIFETIME

    def create_token(self, user_id: int) -> bytes:
        """Create a new authenticated token for user."""
        if not isinstance(user_id, int) or user_id < 0 or user_id > 0xFFFFFFFF:
            raise ValueError("Invalid user ID")
        ts = int(time.time())
        nonce = struct.unpack('>I', os.urandom(4))[0]
        payload = struct.pack('>I', user_id) + struct.pack('>I', ts) + struct.pack('>I', nonce)
        mac = self._compute_hmac(payload)
        token = payload + mac

        token_id = hashlib.sha256(token).hexdigest()[:16]
        self._cache[token_id] = token
        self._cache.move_to_end(token_id)

        if user_id not in self._user_tokens:
            self._user_tokens[user_id] = []
        self._user_tokens[user_id].append(token_id)

        self._evict_if_needed()
        return token

    def _evict_if_needed(self):
        """LRU eviction when cache exceeds max size."""
        while len(self._cache) > self.MAX_CACHE_SIZE:
            self._cache.popitem(last=False)

    def verify_and_get_user(self, token: bytes) -> dict:
        """Verify token and return user info. Main authentication entry point."""
        if not self._validate_token_format(token):
            return {"authenticated": False, "error": "invalid_format"}

        if not self._verify_hmac(token):
            return {"authenticated": False, "error": "invalid_signature"}

        token_id = hashlib.sha256(token).hexdigest()[:16]

        if token_id in self._revoked:
            return {"authenticated": False, "error": "revoked"}

        if self._is_expired(token):
            return {"authenticated": False, "error": "expired"}

        user_id = self._extract_user_id(token)

        # Update access tracking
        if token_id in self._cache:
            self._cache.move_to_end(token_id)

        self._access_log.append({
            "user_id": user_id,
            "token_id": token_id,
            "time": int(time.time())
        })

        return {"authenticated": True, "user_id": user_id, "token_id": token_id}

    def get_user_sessions(self, requesting_user_id: int, target_user_id: int) -> list:
        """Get active sessions for a user. Users can only view their own sessions."""
        if requesting_user_id != target_user_id:
            return []

        sessions = []
        token_ids = self._user_tokens.get(target_user_id, [])
        for tid in token_ids:
            if tid in self._cache and tid not in self._revoked:
                token_data = self._cache[tid]
                sessions.append({
                    "token_id": tid,
                    "created": self._extract_timestamp(token_data),
                    "expired": self._is_expired(token_data)
                })
        return sessions

    def revoke_token(self, requesting_user_id: int, token_id: str) -> bool:
        """Revoke a specific token. Users can only revoke their own tokens."""
        if not isinstance(token_id, str) or len(token_id) != 16:
            return False

        if token_id not in self._cache:
            return False

        token_data = self._cache[token_id]
        token_owner = self._extract_user_id(token_data)

        if requesting_user_id != token_owner:
            return False

        self._revoked.add(token_id)
        return True

    def bulk_verify(self, tokens: list) -> list:
        """Verify multiple tokens at once for batch operations."""
        if not isinstance(tokens, list) or len(tokens) > 100:
            return []
        results = []
        for token in tokens:
            results.append(self.verify_and_get_user(token))
        return results

    def get_access_log(self, admin_token: bytes, offset: int, count: int) -> list:
        """Retrieve access log entries. Requires admin token (user_id 0)."""
        auth_result = self.verify_and_get_user(admin_token)
        if not auth_result.get("authenticated"):
            return []

        if auth_result["user_id"] != 0:
            return []

        # Strict bounds checking for pagination
        log_len = len(self._access_log)
        if not isinstance(offset, int) or not isinstance(count, int):
            return []
        if offset < 0:
            offset = 0
        if count < 0 or count > 1000:
            count = 10

        end_idx = min(offset + count, log_len)
        if offset >= log_len:
            return []

        return self._access_log[offset:end_idx]

    def export_token_metadata(self, admin_token: bytes, user_filter: int = None) -> list:
        """Export token metadata for admin audit. Requires admin (user_id 0)."""
        auth_result = self.verify_and_get_user(admin_token)
        if not auth_result.get("authenticated"):
            return []

        if auth_result["user_id"] != 0:
            return []

        metadata = []
        for token_id, token_data in self._cache.items():
            uid = self._extract_user_id(token_data)
            if user_filter is not None and uid != user_filter:
                continue
            metadata.append({
                "token_id": token_id,
                "user_id": uid,
                "created": self._extract_timestamp(token_data),
                "revoked": token_id in self._revoked
            })
        return metadata

    def refresh_token(self, old_token: bytes) -> bytes:
        """Issue a new token if the old one is valid but close to expiry."""
        auth_result = self.verify_and_get_user(old_token)
        if not auth_result.get("authenticated"):
            return None

        ts = self._extract_timestamp(old_token)
        current = int(time.time())
        remaining = self.TOKEN_LIFETIME - (current - ts)

        # Only refresh if less than 10 minutes remaining
        if remaining > 600:
            return None

        # Revoke old token
        old_id = hashlib.sha256(old_token).hexdigest()[:16]
        self._revoked.add(old_id)

        # Issue new token
        return self.create_token(auth_result["user_id"])
